import { createServer } from 'node:http';
import { createNodeAdapter } from '@cossackframework/node-adapter';

const server = createServer();
const runtime = createNodeAdapter({ maxInstances: 32, idleTimeoutMs: 30_000 });
runtime.attach(server, async () => new Response('framework response'));
if (server.listenerCount('upgrade') !== 1) throw new Error('Expected the runtime upgrade listener');
await runtime.dispose();
if (server.listenerCount('upgrade') !== 0) throw new Error('Disposal must detach the host listener');

import { cossackNode } from '@cossackframework/node-adapter/vite';

const plugin = cossackNode({ entry: '/src/index.ts', shutdownTimeoutMs: 2_000 });
if (plugin.name !== 'cossack-node-development' || plugin.apply !== 'serve') {
  throw new Error('The Node adapter plugin is a Vite development-only integration');
}

import { createSmtpNotificationEmailProvider } from '@cossackframework/node-adapter/notifications';
import { isNotificationDeliveryError } from '@cossackframework/core/notifications';
let sends = 0;
const provider = createSmtpNotificationEmailProvider({ async send() {
  sends++; throw Object.assign(Error('PRIVATE_SMTP_RESPONSE'), { responseCode: 450 });
} });
const message = { to: 'recipient@example.test', from: 'sender@example.test', subject: 'Receipt', text: 'fixture', html: '<p>fixture</p>' };
let rejection: unknown;
try { await provider.send(message, { idempotencyKey: 'fixture-key' }); } catch (error) { rejection = error; }
if (!isNotificationDeliveryError(rejection) || rejection.outcome !== 'rejected' || !rejection.retryable) throw Error('Explicit preaccept rejection should permit a safe runtime retry');
if (provider.idempotency !== 'none' || Number(sends) !== 1 || rejection.message.includes('PRIVATE_')) throw Error('SMTP adapter must not retry or leak transport errors');
const uncertain = createSmtpNotificationEmailProvider({ async send() { throw Error('Unknown transport failure'); } });
let ambiguity: unknown;
try { await uncertain.send(message, { idempotencyKey: 'fixture-key' }); } catch (error) { ambiguity = error; }
if (!isNotificationDeliveryError(ambiguity) || ambiguity.outcome !== 'unknown') throw Error('Ambiguous failures must stop non-idempotent retries');
// Injected structural sender: no network. In applications wrap createNodeEmailSender().
